effect.shader:
// Multi-level advanced sharpen with per-channel and detail controls
vec3 rgb2ycbcr(vec3 c) {
    float y  = dot(c, vec3(0.299, 0.587, 0.114));
    float cb = (c.b - y) * 0.564 + 0.5;
    float cr = (c.r - y) * 0.713 + 0.5;
    return vec3(y, cb, cr);
}
vec3 ycbcr2rgb(vec3 ycc) {
    float y = ycc.x;
    float cb = ycc.y - 0.5;
    float cr = ycc.z - 0.5;
    float r = y + 1.403 * cr;
    float g = y - 0.344 * cb - 0.714 * cr;
    float b = y + 1.773 * cb;
    return vec3(r, g, b);
}
void main() {
    vec2 uv = acScreenNorm;
    vec4 orig = texture2DCv(inputImg.texture, uv);
    float px = 1.0 / acLayerSize.x;
    float py = 1.0 / acLayerSize.y;
    // Multi-scale detail extraction
    vec3 tiny = texture2DCv(inputImg.texture, uv + vec2(px,0)).rgb - orig.rgb;
    tiny += texture2DCv(inputImg.texture, uv - vec2(px,0)).rgb - orig.rgb;
    tiny += texture2DCv(inputImg.texture, uv + vec2(0,py)).rgb - orig.rgb;
    tiny += texture2DCv(inputImg.texture, uv - vec2(0,py)).rgb - orig.rgb;
    tiny *= 0.25 * scaleTiny;

    float smallR = smallDetailSize * 0.5 * px;
    vec3 small = texture2DCv(inputImg.texture, uv + vec2(smallR,0)).rgb - orig.rgb;
    small += texture2DCv(inputImg.texture, uv - vec2(smallR,0)).rgb - orig.rgb;
    small += texture2DCv(inputImg.texture, uv + vec2(0,smallR)).rgb - orig.rgb;
    small += texture2DCv(inputImg.texture, uv - vec2(0,smallR)).rgb - orig.rgb;
    small *= 0.25 * scaleSmall;

    float medR = smallDetailSize * px;
    vec3 medium = texture2DCv(inputImg.texture, uv + vec2(medR,0)).rgb - orig.rgb;
    medium += texture2DCv(inputImg.texture, uv - vec2(medR,0)).rgb - orig.rgb;
    medium += texture2DCv(inputImg.texture, uv + vec2(0,medR)).rgb - orig.rgb;
    medium += texture2DCv(inputImg.texture, uv - vec2(0,medR)).rgb - orig.rgb;
    medium *= 0.25 * scaleMedium;

    float largeR = smallDetailSize * 2.0 * px;
    vec3 large = texture2DCv(inputImg.texture, uv + vec2(largeR,0)).rgb - orig.rgb;
    large += texture2DCv(inputImg.texture, uv - vec2(largeR,0)).rgb - orig.rgb;
    large += texture2DCv(inputImg.texture, uv + vec2(0,largeR)).rgb - orig.rgb;
    large += texture2DCv(inputImg.texture, uv - vec2(0,largeR)).rgb - orig.rgb;
    large *= 0.25 * scaleLarge;

    // Combine all detail levels
    vec3 detail = tiny + small + medium + large;
    // Edge threshold (suppress sharpening on low-contrast areas)
    float edge = length(detail);
    float edgeMask = smoothstep(edgeThresh, edgeThresh+0.1, edge);
    detail *= edgeMask * sharpenAmp;

    // Per-channel and luma/chroma sharpening
    vec3 ycc = rgb2ycbcr(orig.rgb);
    ycc.x += dot(detail, vec3(0.299, 0.587, 0.114)) * sharpenLuma;
    ycc.yz += detail.yz * sharpenChroma * 0.5;
    vec3 rgb = ycbcr2rgb(ycc);
    rgb.r += detail.r * sharpenRed;
    rgb.g += detail.g * sharpenGreen;
    rgb.b += detail.b * sharpenBlue;
    gl_FragColor = vec4(rgb, orig.a);
}
